// Source of truth: this .tsx file (Preact). present.js is generated by `npm --prefix web run build:ts`.
import { h, Fragment, render as mount } from "../../vendor/preact/preact.module.js";
import { mountTerrain } from "../core/terrain.js";
import { holdReady, markReady } from "../core/ready.js";
import { loadSites, windowMetrics, apiWindowMetrics, sealFor } from "../core/data.js";
import { sealEl } from "../core/layers.js";
import { register, t, fmtNum, pickLang, setLang } from "../core/i18n.js";
import { getState, hrefTo, DEFAULT_RULES } from "../core/state.js";
import { evaluateQuestion, gradeChoice } from "./quiz-grading.js";
import { classroomWindows } from "./class-scenarios.js";

register({
  en: {
    "present.badge": "Presenting · Mission",
    "present.exit": "Exit",
    "present.qOf": "Question {n} of 4",
    "present.scenario": "Scenario {n}",
    "present.q1": "Where would you land?",
    "present.q2": "Which site stays within the darkness limit?",
    "present.q3": "Which site keeps Earth radio contact?",
    "present.q4": "Which scenario meets both mission rules?",
    "present.rules": "Battery limit: {night} h in darkness (assumed limit). Radio needs Earth at least every {blackout} h (assumed limit).",
    "present.timer": "Discuss in pairs",
    "present.privacy": "Teacher notes appear only on your laptop, not on the projector.",
    "present.night": "Longest night",
    "present.blackout": "Without seeing Earth",
    "present.reveal": "Reveal answer",
    "present.hide": "Hide answer",
    "present.next": "Next question",
    "present.pick": "Choose", "present.none": "None of these", "present.choose": "Pick a scenario or None, then reveal the answer.",
    "present.selected": "Your choice: {choice}. Reveal to check.", "present.correct": "Correct!", "present.incorrect": "Not this time.",
    "present.answer": "Qualifying scenario(s): {choices}.", "present.noPossible": "None of these scenarios meets this question’s rule.",
    "present.unknown": "There are not enough computed values to determine an answer. Missing data are not marked wrong.",
    "present.unknownChoice": "This scenario has missing measurements, so your choice cannot be graded.",
    "present.timerPaused": "Timer paused. Press to continue."
  },
  "pt-BR": {
    "present.badge": "Apresentando · Missão",
    "present.exit": "Sair",
    "present.qOf": "Pergunta {n} de 4",
    "present.scenario": "Cenário {n}",
    "present.q1": "Onde vocês pousariam?",
    "present.q2": "Qual local fica dentro do limite de horas no escuro?",
    "present.q3": "Qual local mantém contato de rádio com a Terra?",
    "present.q4": "Qual cenário atende às duas regras da missão?",
    "present.rules": "A bateria aguenta {night} h no escuro (limite assumido). O rádio precisa ver a Terra pelo menos a cada {blackout} h (limite assumido).",
    "present.timer": "Discutam em dupla",
    "present.privacy": "Notas do professor aparecem só no seu notebook, não no projetor.",
    "present.night": "Maior noite",
    "present.blackout": "Sem ver a Terra",
    "present.reveal": "Revelar resposta",
    "present.hide": "Ocultar resposta",
    "present.next": "Próxima pergunta",
    "present.pick": "Escolher", "present.none": "Nenhum deles", "present.choose": "Escolha um cenário ou Nenhum deles. Depois, revele a resposta.",
    "present.selected": "Sua escolha: {choice}. Revele para conferir.", "present.correct": "Você acertou!", "present.incorrect": "Não foi dessa vez.",
    "present.answer": "Cenário(s) que atende(m): {choices}.", "present.noPossible": "Nenhum destes cenários atende à regra desta pergunta.",
    "present.unknown": "Ainda não há dados suficientes para concluir. Dados ausentes não contam como erro.",
    "present.unknownChoice": "Faltam medições para este cenário; sua escolha não pode ser avaliada.",
    "present.timerPaused": "Cronômetro pausado. Pressione para continuar."
  }
});

// No shell on this page: honour ?lang= (set by the other screens) and the browser language, and keep <html lang> in sync.
setLang(pickLang(getState().lang));
document.title = `MoonProof · ${t("present.badge")}`;

holdReady();
const doc = await loadSites();
const LETTERS = ["A", "B", "C"];
// Scenarios are real sites; the terrain marker shows the scenario letter instead of the site number.
const st = getState();
const chosenWindows = classroomWindows(doc.sites, location.hash, st);
const scenarios = chosenWindows.map((w, i) => ({ ...w.site, n: LETTERS[i] }));
const nightLimit = Number(st.night ?? DEFAULT_RULES.night);
const blackoutLimit = Number(st.blackout ?? DEFAULT_RULES.blackout);

await mountTerrain(document.getElementById("terrain")!, {
  sites: scenarios,
  selected: st.site || scenarios[0]?.id
});

const metrics = await Promise.all(chosenWindows.map((w) => apiWindowMetrics(doc, w.site, w.start, w.hours || 336)));
type Metrics = (typeof metrics)[number];

let qIndex = 1;
let revealed = false;
let chosen: string | null = null;
let secondsLeft = 120;
let running = true;

setInterval(() => {
  if (running && secondsLeft > 0) {
    secondsLeft -= 1;
    const valEl = document.getElementById("timer-val");
    if (valEl) valEl.textContent = fmtClock(secondsLeft);
  }
}, 1000);

/** Mounts a DOM node built by the core (seals) inside a Preact tree. */
function Node({ node }: { node: Node | null }) {
  return h("mp-node" as "span", { style: { display: "contents" }, ref: (host: HTMLElement | null) => { if (host && node && host.firstChild !== node) host.replaceChildren(node); } });
}
/** Drops the previous tree first, so every pass builds fresh nodes (as the old innerHTML did). */
function paint(vnode: preact.ComponentChild, host: HTMLElement) { mount(null, host); host.replaceChildren(); mount(vnode, host); }
const $ = (id: string) => document.getElementById(id) as HTMLElement;

const IconNight = () => <svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="#D9AE4E" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M8 15a4 4 0 0 1 8 0" /><path d="M2 15h20" /><path d="M12 7v2M5 10l1.4 1.4M19 10l-1.4 1.4" /><path d="M5 19h14" stroke-dasharray="2 2" /></svg>;
const IconEarth = () => <svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="#9DB4CC" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 12v9" /><path d="M8 21h8" /><circle cx="12" cy="10" r="2" /><path d="M4 4l16 16" /></svg>;
const IconX = () => <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18" /></svg>;
const IconInfo = () => <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#9DB4CC" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9" /><path d="M12 11v6M12 7.5v.5" /></svg>;

function fmtClock(sec: number): string {
  const m = Math.floor(sec / 60);
  const s = String(sec % 60).padStart(2, "0");
  return `${m}:${s}`;
}

function draw() {
  const answer = evaluateQuestion(qIndex, metrics, { night: nightLimit, blackout: blackoutLimit });
  $("present-badge").textContent = t("present.badge");
  const exitEl = $("present-exit") as HTMLAnchorElement;
  paint(<><IconX />{t("present.exit")}</>, exitEl);
  exitEl.href = hrefTo("activity.html") + location.hash;

  const progEl = $("present-progress");
  progEl.setAttribute("aria-label", t("present.qOf", { n: qIndex }));
  paint(<>{[1, 2, 3, 4].map((i) => <span class={`mp-progress-seg ${i <= qIndex ? "is-done" : ""}`} />)}</>, progEl);

  const qKey = `present.q${qIndex}`;
  paint(<>
    <div class="mp-q-idx">{t("present.qOf", { n: qIndex })}</div>
    <h1>{t(qKey)}</h1>
    <p>{t("present.rules", { night: nightLimit, blackout: blackoutLimit })}</p>
  </>, $("present-question"));

  const timerEl = $("present-timer");
  paint(<><span class="mp-timer-label">{t("present.timer")}</span><span id="timer-val" class="mp-timer-val">{fmtClock(secondsLeft)}</span></>, timerEl);
  timerEl.setAttribute("aria-pressed", String(running));
  timerEl.setAttribute("aria-label", running ? t("present.timer") : t("present.timerPaused"));
  timerEl.onclick = () => { running = !running; draw(); };

  paint(<><IconInfo /><span>{t("present.privacy")}</span></>, $("present-privacy"));

  paint(<>{scenarios.map((s, idx) => {
    const m = metrics[idx];
    const pass = answer.verdicts[idx];
    const nVal = m.longestDarkH.value == null ? t("nd") : `${fmtNum(m.longestDarkH.value)} h`;
    const bVal = m.longestBlackoutH.value == null ? t("nd") : `${fmtNum(m.longestBlackoutH.value)} h`;
    return (
      <article class={"mp-glass mp-sc-card" + (chosen === String(s.n) ? " is-chosen" : "") + (revealed && pass === true ? " is-winner" : "") + (revealed && chosen === String(s.n) && pass === false ? " is-fail" : "")}>
        <button type="button" class="mp-quiz-pick" aria-pressed={chosen === String(s.n)} onClick={() => { chosen = String(s.n); draw(); }}>{t("present.pick")} {s.n}</button>
        <div class="mp-sc-head"><span class="mp-sc-letter">{s.n}</span><span class="mp-sc-title"><span class="mp-sc-name">{t("present.scenario", { n: s.n })}</span><span class="mp-sc-site">{s.name}</span></span><span class="mp-sc-seal"><Node node={sealEl(sealFor(m.longestDarkH.value == null ? "NOT_COMPUTED" : doc.status))} /></span></div>
        <div class="mp-sc-row"><IconNight /><span class="mp-sc-label">{t("present.night")}</span><strong class="mp-sc-val">{nVal}</strong></div>
        <div class="mp-sc-row"><IconEarth /><span class="mp-sc-label">{t("present.blackout")}</span><strong class="mp-sc-val">{bVal}</strong></div>
      </article>
    );
  })}</>, $("present-cards"));

  const none = $("btn-none") as HTMLButtonElement;
  none.textContent = t("present.none");
  none.setAttribute("aria-pressed", String(chosen === "none"));
  none.onclick = () => { chosen = "none"; draw(); };
  const result = gradeChoice(chosen, answer);
  const feedback = $("present-feedback");
  feedback.dataset.status = revealed ? result : "unanswered";
  feedback.textContent = revealed
    ? answer.status === "unknown" ? t("present.unknown")
      : result === "unknown" ? t("present.unknownChoice")
      : (result === "correct" ? t("present.correct") + " " : result === "incorrect" ? t("present.incorrect") + " " : "") +
        (answer.correctIds.includes("none") ? t("present.noPossible") : t("present.answer", { choices: answer.correctIds.join(", ") }))
    : chosen ? t("present.selected", { choice: chosen === "none" ? t("present.none") : chosen }) : t("present.choose");
  const btnReveal = $("btn-reveal");
  btnReveal.textContent = revealed ? t("present.hide") : t("present.reveal");
  btnReveal.onclick = () => { revealed = !revealed; draw(); };

  const btnNext = $("btn-next");
  btnNext.textContent = t("present.next");
  btnNext.onclick = () => {
    qIndex = qIndex >= 4 ? 1 : qIndex + 1;
    revealed = false;
    chosen = null;
    draw();
  };
}

draw();
markReady();
